update public.organizations o set email_domain = case when substring(lower(split_part(m.email,'@',2)) from '[^.]+\.[^.]+$') in ('co.in','net.in','org.in','gen.in','firm.in','ind.in','co.uk','org.uk','me.uk','ltd.uk','plc.uk','ac.uk','gov.uk','com.au','net.au','org.au','edu.au','co.nz','com.br','com.mx','com.sg','com.my','com.hk','co.jp','or.jp','ne.jp','co.kr','com.cn','net.cn','org.cn','co.za','com.tr','com.ar','com.ph','co.id','com.sa','com.eg','co.il','com.tw','com.vn','com.pk','com.bd','com.ng') then substring(lower(split_part(m.email,'@',2)) from '[^.]+\.[^.]+\.[^.]+$') else substring(lower(split_part(m.email,'@',2)) from '[^.]+\.[^.]+$') end from public.org_members m where m.org_id = o.id and m.is_owner and o.email_domain is null;